function demoMain(idx,label){
  var ins=[["MOV AX,1","B8 01 00"],["ADD AX,BX","01 D8"],["JMP loop","EB F9"]];
  var a=ins[idx%ins.length];
  return "["+label+"] '"+a[0]+"' assembled -> bytes "+a[1];
}

